1	import type {
2	  EventTimelineItem,
3	  RoomInterface,
4	  TaskHandleInterface,
5	  TimelineInterface,
6	} from "@unomed/react-native-matrix-sdk";
7	import {
8	  DateDividerMode,
9	  RoomMessageEventMessageType,
10	  TimelineDiff_Tags,
11	  TimelineFilter,
12	  TimelineFocus,
13	  TimelineReadReceiptTracking,
14	} from "@unomed/react-native-matrix-sdk";
15	import { getEventId } from "modules/matrix-client/utils";
16	import { useCallback, useEffect, useRef, useState } from "react";
17	
18	//TODO: Make a timeline module
19	
20	interface UseMediaTimelineProps {
21	  room: RoomInterface | undefined;
22	  roomId: string;
23	}
24	
25	export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
26	  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
27	  const [loading, setLoading] = useState(true);
28	  const eventIdsRef = useRef<Set<string>>(new Set());
29	  const timelineRef = useRef<TimelineInterface | null>(null);
30	
31	  const upsertMediaItems = useCallback((incoming: EventTimelineItem[]) => {
32	    setMediaItems((prev) => {
33	      const next = [...prev];
34	      for (const event of incoming) {
35	        const id = getEventId(event);
36	        if (!id || eventIdsRef.current.has(id)) continue;
37	
38	        eventIdsRef.current.add(id);
39	        next.push(event);
40	      }
41	      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
42	    });
43	  }, []);
44	
45	  useEffect(() => {
46	    if (!room) return;
47	
48	    setLoading(true);
49	    setMediaItems([]);
50	    eventIdsRef.current.clear();
51	
52	    let timelineListenerHandle: TaskHandleInterface | null = null;
53	
54	    const initMediaTimeline = async () => {
55	      try {
56	        const timeline = await room.timelineWithConfiguration({
57	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
58	          filter: new TimelineFilter.OnlyMessage({
59	            types: [
60	              RoomMessageEventMessageType.Image,
61	              RoomMessageEventMessageType.Video,
62	              RoomMessageEventMessageType.File,
63	              RoomMessageEventMessageType.Audio,
64	            ],
65	          }),
66	          internalIdPrefix: "media_",
67	          dateDividerMode: DateDividerMode.Daily,
68	          trackReadReceipts: TimelineReadReceiptTracking.Disabled,
69	          reportUtds: false,
70	        });
71	
72	        timelineRef.current = timeline;
73	
74	        // Set up timeline listener for updates
75	        timelineListenerHandle = await timeline.addListener({
76	          onUpdate: (diffs) => {
77	            diffs.forEach((diff) => {
78	              const change = diff.tag;
79	              switch (change) {
80	                case TimelineDiff_Tags.Append: {
81	                  const newItems = diff.inner.values;
82	                  if (newItems.length) {
83	                    const eventItems = newItems
84	                      .map((i) => i.asEvent())
85	                      .filter((i): i is EventTimelineItem => !!i);
86	                    if (eventItems.length > 0) upsertMediaItems(eventItems);
87	                  }
88	                  break;
89	                }
90	                case TimelineDiff_Tags.Insert:
91	                case TimelineDiff_Tags.PushFront:
92	                case TimelineDiff_Tags.PushBack: {
93	                  const { value } = diff.inner;
94	                  const ev = value.asEvent();
95	                  if (ev) upsertMediaItems([ev]);
96	                  break;
97	                }
98	                case TimelineDiff_Tags.Set: {
99	                  const { value } = diff.inner;
100	                  const ev = value.asEvent();
101	                  if (ev) {
102	                    const id = getEventId(ev);
103	                    if (!id) break;
104	
105	                    setMediaItems((prev) => {
106	                      const existingIndex = prev.findIndex(
107	                        (item) => getEventId(item) === id,
108	                      );
109	                      if (existingIndex >= 0) {
110	                        const next = [...prev];
111	                        next[existingIndex] = ev;
112	                        return next;
113	                      }
114	                      return prev;
115	                    });
116	                  }
117	                  break;
118	                }
119	                case TimelineDiff_Tags.Remove: {
120	                  const { index: removeIndex } = diff.inner;
121	                  setMediaItems((prev) => {
122	                    const next = prev.filter((_, idx) => idx !== removeIndex);
123	                    eventIdsRef.current = new Set(
124	                      next
125	                        .map((item) => getEventId(item))
126	                        .filter(Boolean) as string[],
127	                    );
128	                    return next;
129	                  });
130	                  break;
131	                }
132	                case TimelineDiff_Tags.Reset: {
133	                  const resetItems = diff.inner.values;
134	                  if (resetItems.length) {
135	                    const eventItems = resetItems
136	                      .map((i) => i.asEvent())
137	                      .filter((i): i is EventTimelineItem => !!i);
138	
139	                    const seenIds = new Set<string>();
140	                    const newMediaItems: EventTimelineItem[] = [];
141	
142	                    for (const event of eventItems) {
143	                      const id = getEventId(event);
144	                      if (id && !seenIds.has(id)) {
145	                        seenIds.add(id);
146	                        newMediaItems.push(event);
147	                      }
148	                    }
149	
150	                    eventIdsRef.current = seenIds;
151	                    setMediaItems(
152	                      newMediaItems.sort(
153	                        (a, b) => Number(b.timestamp) - Number(a.timestamp),
154	                      ),
155	                    );
156	                  }
157	                  break;
158	                }
159	                case TimelineDiff_Tags.Clear: {
160	                  eventIdsRef.current.clear();
161	                  setMediaItems([]);
162	                  break;
163	                }
164	                default:
165	                  break;
166	              }
167	            });
168	          },
169	        });
170	
171	        // Paginate backwards until we reach the start of the timeline
172	        let reachedStart = false;
173	        while (!reachedStart) {
174	          reachedStart = await timeline.paginateBackwards(100);
175	        }
176	
177	        setLoading(false);
178	      } catch (error) {
179	        console.error("Failed to initialize media timeline:", error);
180	        setLoading(false);
181	      }
182	    };
183	
184	    initMediaTimeline();
185	
186	    return () => {
187	      timelineListenerHandle?.cancel?.();
188	      timelineRef.current = null;
189	    };
190	  }, [roomId, room, upsertMediaItems]);
191	
192	  return {
193	    mediaItems,
194	    loading,
195	  };
196	};
197

1	import type {
2	  EventTimelineItem,
3	  RoomInterface,
4	  TaskHandleInterface,
5	  TimelineInterface,
6	  TimelineItemInterface,
7	} from "@unomed/react-native-matrix-sdk";
8	import {
9	  DateDividerMode,
10	  ReceiptType,
11	  TimelineDiff_Tags,
12	  TimelineFilter,
13	  TimelineFocus,
14	  TimelineReadReceiptTracking,
15	} from "@unomed/react-native-matrix-sdk";
16	import {
17	  getItemUniqueKey,
18	  getTransactionId,
19	} from "modules/matrix-client/utils";
20	import { NavigationContainerRef } from "modules/navigation/const";
21	import { useCallback, useEffect, useRef, useState } from "react";
22	import { AppState } from "react-native";
23	import { offlineToastHelper } from "shared/utils";
24	
25	interface Props {
26	  room: RoomInterface | undefined;
27	  roomId: string;
28	}
29	
30	const TIMELINE_PAGE_SIZE = 20;
31	const MIN_INITIAL_EVENTS = 10;
32	const ENABLE_TIMELINE_DEBUG = __DEV__;
33	
34	export const useRoomTimeline = ({ room, roomId }: Props) => {
35	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
36	  const eventIdsRef = useRef<Set<string>>(new Set());
37	  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
38	  const timelineRef = useRef<TimelineInterface | null>(null);
39	  const isPaginatingRef = useRef(false);
40	  const reachedStartRef = useRef(false);
41	  // const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
42	  const [isDirect, setIsDirect] = useState(false);
43	  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
44	  const pendingTransactionIdsQueue = useRef<string[]>([]);
45	  const rebuildTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
46	  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
47	    item.asEvent() ?? null;
48	
49	  const rebuildEventsFromTimelineItems = useCallback(() => {
50	    const seenIds = new Set<string>();
51	    const nextEvents: EventTimelineItem[] = [];
52	
53	    for (const item of timelineItemsRef.current) {
54	      if (!item) continue;
55	      const key = getItemUniqueKey(item);
56	      if (key) {
57	        if (seenIds.has(key)) continue;
58	        seenIds.add(key);
59	      }
60	      nextEvents.push(item);
61	    }
62	
63	    eventIdsRef.current = seenIds;
64	    setEvents(nextEvents);
65	  }, []);
66	
67	  const markAsRead = useCallback(async () => {
68	    if (!room) return;
69	    if (AppState.currentState !== "active") return;
70	
71	    try {
72	      await room.markAsRead(ReceiptType.Read);
73	    } catch (error) {
74	      console.error("Failed to mark room as read:", error);
75	    }
76	  }, [room]);
77	
78	  const loadMoreMessages = useCallback(async () => {
79	    if (
80	      !timelineRef.current ||
81	      isPaginatingRef.current ||
82	      reachedStartRef.current
83	    ) {
84	      return;
85	    }
86	
87	    isPaginatingRef.current = true;
88	
89	    try {
90	      const hitStart =
91	        await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
92	      if (!hitStart) return;
93	      reachedStartRef.current = true;
94	    } catch (error) {
95	      console.error("Failed to load more messages:", error);
96	    } finally {
97	      isPaginatingRef.current = false;
98	    }
99	  }, []);
100	
101	  //Hide for now pinned events, because it's not working as expected
102	  // useEffect(() => {
103	  //   if (!room) return;
104	  //   setPinnedEventIds([]);
105	  //   room
106	  //     .roomInfo()
107	  //     .then((info) => {
108	  //       console.log(info);
109	  //       setPinnedEventIds(info.pinnedEventIds || []);
110	  //     })
111	  //     .catch(console.error);
112	  //   const handle = room.subscribeToRoomInfoUpdates({
113	  //     call: (info) => {
114	  //       console.log(info);
115	  //       setPinnedEventIds(info.pinnedEventIds || []);
116	  //     },
117	  //   });
118	  //   return () => handle.cancel();
119	  // }, [room, setPinnedEventIds]);
120	
121	  useEffect(() => {
122	    if (!room) return;
123	
124	    // Reset state when room changes
125	    setEvents([]);
126	    timelineItemsRef.current = [];
127	    eventIdsRef.current.clear();
128	    pendingTransactionIdsQueue.current = [];
129	
130	    let timelineListenerHandle: TaskHandleInterface | null = null;
131	    let isDisposed = false;
132	
133	    const initRoomTimeline = async () => {
134	      try {
135	        const timeline = await room.timelineWithConfiguration({
136	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
137	          filter: new TimelineFilter.All(),
138	          internalIdPrefix: undefined,
139	          dateDividerMode: DateDividerMode.Daily,
140	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
141	          reportUtds: false,
142	        });
143	
144	        // Store timeline in ref for reuse in pagination
145	        timelineRef.current = timeline;
146	
147	        // Set up listener BEFORE paginateBackwards so the SDK's initial
148	        // cached diffs (from SQLite) are received immediately — no network needed.
149	        // Set up timeline listener for real-time updates
150	        timelineListenerHandle = await timeline.addListener({
151	          onUpdate: (diffs) => {
152	            const beforeCount = timelineItemsRef.current.length;
153	            diffs.forEach((diff) => {
154	              const change = diff.tag;
155	              const timelineItems = timelineItemsRef.current;
156	              switch (change) {
157	                case TimelineDiff_Tags.Append: {
158	                  if (diff.inner.values.length > 0) {
159	                    timelineItems.push(...diff.inner.values.map(toEventItem));
160	                  }
161	                  break;
162	                }
163	                case TimelineDiff_Tags.Insert: {
164	                  const { index, value } = diff.inner;
165	                  timelineItems.splice(index, 0, toEventItem(value));
166	                  break;
167	                }
168	                case TimelineDiff_Tags.Set: {
169	                  const { index, value } = diff.inner;
170	                  const ev = toEventItem(value);
171	                  timelineItems[index] = ev;
172	
173	                  // transactionId -> eventId transition can arrive in an order where
174	                  // a stale local echo still exists elsewhere in the list.
175	                  if (
176	                    ev?.isOwn &&
177	                    !ev.localSendState &&
178	                    pendingTransactionIdsQueue.current.length > 0
179	                  ) {
180	                    const txId = pendingTransactionIdsQueue.current.shift();
181	                    if (txId) {
182	                      const txIndex = timelineItems.findIndex((item) => {
183	                        if (!item) return false;
184	                        return getItemUniqueKey(item) === txId;
185	                      });
186	                      if (txIndex !== -1) {
187	                        timelineItems[txIndex] = ev;
188	                      }
189	                    }
190	                  }
191	                  break;
192	                }
193	                case TimelineDiff_Tags.Remove: {
194	                  const { index: removeIndex } = diff.inner;
195	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
196	                    timelineItems.splice(removeIndex, 1);
197	                  }
198	                  break;
199	                }
200	                case TimelineDiff_Tags.PushFront: {
201	                  const { value } = diff.inner;
202	                  timelineItems.unshift(toEventItem(value));
203	                  break;
204	                }
205	                case TimelineDiff_Tags.PushBack: {
206	                  const { value } = diff.inner;
207	                  const ev = toEventItem(value);
208	                  timelineItems.push(ev);
209	                  if (ev) {
210	                    const txId = getTransactionId(ev);
211	                    if (txId) {
212	                      pendingTransactionIdsQueue.current.push(txId);
213	                    }
214	                  }
215	                  break;
216	                }
217	                case TimelineDiff_Tags.PopFront: {
218	                  timelineItems.shift();
219	                  break;
220	                }
221	                case TimelineDiff_Tags.PopBack: {
222	                  timelineItems.pop();
223	                  break;
224	                }
225	                case TimelineDiff_Tags.Reset: {
226	                  const resetItems = diff.inner.values;
227	                  pendingTransactionIdsQueue.current = [];
228	                  timelineItemsRef.current = resetItems.map(toEventItem);
229	
230	                  const eventItems = timelineItemsRef.current.filter(
231	                    (i): i is EventTimelineItem => !!i,
232	                  );
233	                  pendingTransactionIdsQueue.current = eventItems
234	                    .map(getTransactionId)
235	                    .filter((id): id is string => !!id);
236	                  break;
237	                }
238	                case TimelineDiff_Tags.Truncate: {
239	                  const { length: cut } = diff.inner;
240	                  timelineItems.length = cut;
241	                  break;
242	                }
243	                case TimelineDiff_Tags.Clear: {
244	                  timelineItemsRef.current = [];
245	                  pendingTransactionIdsQueue.current = [];
246	                  eventIdsRef.current = new Set();
247	                  setEvents([]);
248	                  break;
249	                }
250	                default:
251	                  console.log("Unknown timeline change type:", change);
252	              }
253	            });
254	
255	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
256	              if (rebuildTimerRef.current) {
257	                clearTimeout(rebuildTimerRef.current);
258	              }
259	              rebuildTimerRef.current = setTimeout(
260	                rebuildEventsFromTimelineItems,
261	                0,
262	              );
263	            }
264	
265	            if (ENABLE_TIMELINE_DEBUG) {
266	              const afterCount = timelineItemsRef.current.length;
267	              const tags = diffs.map((d) => d.tag).join(", ");
268	              console.log(
269	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
270	              );
271	            }
272	          },
273	        });
274	
275	        // Paginate after the listener is set up so events flow through it.
276	        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
277	        isPaginatingRef.current = true;
278	        (async () => {
279	          try {
280	            let hitStart = false;
281	            while (!isDisposed && !hitStart) {
282	              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
283	              if (hitStart) {
284	                reachedStartRef.current = true;
285	                break;
286	              }
287	              const eventCount =
288	                timelineItemsRef.current.filter(Boolean).length;
289	              if (eventCount >= MIN_INITIAL_EVENTS) break;
290	            }
291	          } catch (error) {
292	            if (!isDisposed) {
293	              console.warn("Failed to load initial messages:", error);
294	            }
295	          } finally {
296	            isPaginatingRef.current = false;
297	          }
298	        })();
299	      } catch (error) {
300	        console.error("Failed to initialize room timeline:", error);
301	        offlineToastHelper("Failed to load the messages. Please try again.");
302	        NavigationContainerRef.goBack();
303	        return null;
304	      }
305	    };
306	
307	    initRoomTimeline();
308	
309	    return () => {
310	      isDisposed = true;
311	      timelineListenerHandle?.cancel?.();
312	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
313	      timelineRef.current = null;
314	      timelineItemsRef.current = [];
315	      isPaginatingRef.current = false;
316	      reachedStartRef.current = false;
317	    };
318	  }, [rebuildEventsFromTimelineItems, room, roomId]);
319	
320	  useEffect(() => {
321	    markAsRead().catch(console.error);
322	    room?.isDirect().then(setIsDirect).catch(console.error);
323	  }, [room, markAsRead]);
324	
325	  return {
326	    events,
327	    timelineRef,
328	    isPaginatingRef,
329	    reachedStartRef,
330	    isDirect,
331	    loadMoreMessages,
332	    markAsRead,
333	  };
334	};
