1	import { atom } from "jotai";
2	
3	/** One atom; two sheets subscribe. isFailedEcho(payload.event) routes between
4	MessageContentBottomSheet (normal) and FailedEchoBottomSheet (send failed).  */
5	const longPressPayload = atom<TimelineLongPressPayload | null>(null);
6	const replyPayload = atom<TimelineReplyPayload | null>(null);
7	const editPayload = atom<TimelineEditPayload | null>(null);
8	const forwardPayload = atom<TimelineLongPressPayload | null>(null);
9	const reportPayload = atom<TimelineReportPayload | null>(null);
10	const scrollToEventId = atom<string | null>(null);
11	const seenByUsers = atom<TimelineSeenByUser[] | null>(null);
12	const reactionsPayload = atom<TimelineReaction[] | null>(null);
13	const imageViewerPayload = atom<ImageViewerPayload | null>(null);
14	const imageInfoPayload = atom<ImageInfoPayload | null>(null);
15	const videoInfoPayload = atom<VideoInfoPayload | null>(null);
16	const pinnedEventIds = atom<string[]>([]);
17	const shieldPayload = atom<TimelineShieldPayload | null>(null);
18	const mediaViewerPayload = atom<MediaViewerPayload | null>(null);
19	/** Media items (images + videos) from the currently active room timeline.
20	Filled by the room's RoomTimeline so message taps can open a swipeable viewer. */
21	const roomMediaItems = atom<EventTimelineItem[]>([]);
22	
23	export const TimelineAtoms = {
24	  longPressPayload,
25	  replyPayload,
26	  editPayload,
27	  forwardPayload,
28	  reportPayload,
29	  scrollToEventId,
30	  seenByUsers,
31	  reactionsPayload,
32	  imageViewerPayload,
33	  imageInfoPayload,
34	  videoInfoPayload,
35	  pinnedEventIds,
36	  shieldPayload,
37	  mediaViewerPayload,
38	  roomMediaItems,
39	};
