1	import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
2	import { FlashList, type FlashListRef } from "@shopify/flash-list";
3	import { animateParallel, Block, Text } from "@prototyp/skeletor";
4	import {
5	  type EventTimelineItem,
6	  ProfileDetails_Tags,
7	} from "@unomed/react-native-matrix-sdk";
8	import { format } from "date-fns";
9	import { useAtom, useSetAtom } from "jotai";
10	import { getEventId } from "modules/matrix-client/utils";
11	import { TimelineAtoms } from "modules/timeline/jotai";
12	import {
13	  type FC,
14	  useCallback,
15	  useEffect,
16	  useMemo,
17	  useRef,
18	  useState,
19	} from "react";
20	import { Dimensions, Image, Modal, StyleSheet, View } from "react-native";
21	import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
22	import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
23	import { Colors, TextSize } from "shared/styles";
24	import { BlurGradientOverlay } from "../blur-gradient-overlay";
25	import { Button } from "../button";
26	import { MediaImagePage } from "./MediaImagePage";
27	import { MediaVideoPage } from "./MediaVideoPage";
28	import { getMediaKind } from "./utils";
29	
30	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
31	
32	const VIEWABILITY_CONFIG = { itemVisiblePercentThreshold: 80 };
33	
34	export const MediaViewerModal: FC = () => {
35	  const [payload, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
36	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
37	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
38	  const listRef = useRef<FlashListRef<EventTimelineItem>>(null);
39	  const [showControls, setShowControls] = useState(true);
40	  const [currentIndex, setCurrentIndex] = useState(0);
41	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
42	
43	  const visible = !!payload;
44	  const roomId = payload?.roomId ?? null;
45	
46	  const items = useMemo<EventTimelineItem[]>(() => {
47	    if (!payload) return [];
48	    const filtered = payload.items.filter(
49	      (item) => getMediaKind(item) !== null,
50	    );
51	    // Source is newest-first; reverse so newest sits on the right edge
52	    // and swiping right reveals older media.
53	    return filtered.reverse();
54	  }, [payload]);
55	
56	  const initialIndex = useMemo(() => {
57	    if (!payload) return 0;
58	    const idx = items.findIndex(
59	      (item) => getEventId(item) === payload.initialEventId,
60	    );
61	    return idx >= 0 ? idx : 0;
62	  }, [items, payload]);
63	
64	  useEffect(() => {
65	    if (!visible) return;
66	    setCurrentIndex(initialIndex);
67	  }, [visible, initialIndex]);
68	
69	  useEffect(() => {
70	    if (!visible || initialIndex === 0) return;
71	    const id = setTimeout(() => {
72	      listRef.current?.scrollToIndex({
73	        index: initialIndex,
74	        animated: false,
75	      });
76	    }, 0);
77	    return () => clearTimeout(id);
78	  }, [visible, initialIndex]);
79	
80	  const currentItem = items[currentIndex];
81	  const currentKind = currentItem ? getMediaKind(currentItem) : null;
82	
83	  const senderName = useMemo(() => {
84	    if (!currentItem) return null;
85	    if (currentItem.senderProfile.tag === ProfileDetails_Tags.Ready) {
86	      return (
87	        currentItem.senderProfile.inner.displayName ?? currentItem.sender
88	      );
89	    }
90	    return currentItem.sender;
91	  }, [currentItem]);
92	
93	  const formattedDate = useMemo(() => {
94	    if (!currentItem) return null;
95	    return format(Number(currentItem.timestamp), "MMM d, HH:mm");
96	  }, [currentItem]);
97	
98	  const controlsAnimation = useRef(
99	    animateParallel(
100	      { translateY: [-120, 0], opacity: [0, 1] },
101	      { duration: 280 },
102	    ),
103	  ).current;
104	
105	  useEffect(() => {
106	    if (showControls) controlsAnimation.start();
