245	      );
246	    },
247	    [roomId, openMemberDetails],
248	  );
249	
250	  const keyExtractor = useCallback((item: TimelineListItem) => {
251	    if (item.type === "divider") return item.id;
252	    if (item.type === "group") return item.id;
253	
254	    return getItemUniqueKey(item.data) ?? "";
255	  }, []);
256	
257	  useEffect(() => {
258	    return () => {
259	      setReactionsPayload(null);
260	      setSeenByUsers(null);
261	      setScrollToEventId(null);
262	      setShieldPayload(null);
263	    };
264	  }, []);
265	
266	  return (
267	    <>
268	      <KeyboardAvoidingView style={styles.flex} behavior="padding">
269	        {!!violatingUsers.length && (
270	          <RoomIdentityBanner
271	            users={violatingUsers}
272	            isLoading={isPinViolatingUsersLoading}
273	            onDismiss={pinViolatingUsers}
274	          />
275	        )}
276	        <FlashList
277	          ref={flashListRef}
278	          data={reversedEvents}
279	          inverted
280	          keyExtractor={keyExtractor}
281	          contentContainerStyle={styles.listContent}
282	          onContentSizeChange={handleContentSizeChange}
283	          onScroll={handleOnScroll}
284	          renderItem={renderItem}
285	        />
286	
287	        <RoomInput roomId={roomId} />
